package medroute;
import java.util.*;import stringalgo.*;import dynamicprogramming.*;import suffix.*;import randomized.*;import parallel.*;import approximation.*;import graph.*;
public class AlgorithmDemo { public static void run(Scanner sc){System.out.println("\n============= DSA DEMONSTRATIONS =============");System.out.println("1 KMP | 2 Z | 3 Rabin-Karp | 4 Aho-Corasick");System.out.println("5 Levenshtein | 6 Damerau | 7 Weighted Edit");System.out.println("8 Suffix Array | 9 LCP | 10 Suffix Automaton");System.out.println("11 Dijkstra | 12 Max Flow | 13 Vertex Cover");System.out.println("14 Randomized QuickSort | 15 Reservoir Sampling | 16 Miller-Rabin");System.out.println("17 Parallel Reduce | 18 Blelloch Scan | 0 Back");System.out.print("Choose: ");String c=sc.nextLine();switch(c){case "1"->System.out.println("KMP index: "+KMP.search("Paracetamol emergency supply","emergency"));case "2"->System.out.println("Z contains: "+ZAlgorithm.contains("medical supply delivery","supply"));case "3"->System.out.println("Rabin-Karp index: "+RabinKarp.search("MED-2026-EMERGENCY-001","EMERGENCY"));case "4"->{AhoCorasick a=new AhoCorasick();a.add("oxygen");a.add("icu");a.add("urgent");a.build();System.out.println("Keywords: "+a.find("Urgent oxygen support for ICU"));}case "5"->System.out.println("Levenshtein(paracetmol, paracetamol) = "+LevenshteinDistance.distance("paracetmol","paracetamol"));case "6"->System.out.println("Damerau(paracetmaol, paracetamol) = "+DamerauLevenshtein.distance("paracetmaol","paracetamol"));case "7"->System.out.println("Weighted distance = "+WeightedEditDistance.distance("ibuprofne","ibuprofen",1,1,2));case "8"->{int[] sa=SuffixArray.build("medical");System.out.println("Suffix array: "+Arrays.toString(sa));}case "9"->{String s="banana";int[] sa=SuffixArray.build(s);System.out.println("LCP for banana: "+Arrays.toString(LCPArray.build(s,sa)));}case "10"->{SuffixAutomaton sa=new SuffixAutomaton("paracetamol");System.out.println("Suffix automaton contains 'para': "+sa.contains("para")+", states="+sa.states());}case "11"->{Graph g=new Graph(4);g.addUndirectedEdge(0,1,5);g.addUndirectedEdge(1,2,2);g.addUndirectedEdge(2,3,3);System.out.println("Dijkstra: "+Arrays.toString(Dijkstra.shortestPaths(g,0)));}case "12"->{int[][] cap={{0,3,2,0},{0,0,0,2},{0,0,0,2},{0,0,0,0}};System.out.println("Max flow: "+EdmondsKarp.maxFlow(cap,0,3));}case "13"->{int[][] e={{0,1},{1,2},{2,3},{3,0}};System.out.println("2-approx vertex cover: "+VertexCover.approximate(4,e));}case "14"->{int[] a={42,5,17,9,1,30};RandomizedQuickSort.sort(a);System.out.println("Sorted: "+Arrays.toString(a));}case "15"->System.out.println("Sample: "+ReservoirSampling.sample(List.of("W1","W2","W3","W4","W5"),3));case "16"->System.out.println("Miller-Rabin: 1000003 prime? "+MillerRabin.isPrime(1000003));case "17"->{try{System.out.println("Parallel sum: "+ParallelReduce.sum(new int[]{10,20,30,40,50},2));}catch(Exception e){System.out.println(e.getMessage());}}case "18"->System.out.println("Prefix scan: "+Arrays.toString(BlellochScan.prefixSum(new int[]{10,20,30,40})));default->System.out.println("Back/invalid choice.");}}
}
